-- Seed de datos de ejemplo para snack-store-api
-- Reutilizable: ON CONFLICT (id) DO NOTHING hace las inserciones idempotentes.
-- En productos, al re-ejecutar solo se refresca image_url (no pisa datos editados).
-- Imágenes: fotos reales desde el CDN de Unsplash (images.unsplash.com).
-- 24 productos con imagen y 2 sin imagen (Maní Salado y Atún en Lata) para que
-- el front pueda probar el caso 'sin imagen' / error de carga.

-- ===== Categorías =====
ON CONFLICT (id) DO NOTHING;

-- ===== Productos =====
ON CONFLICT (id) DO UPDATE SET image_url = EXCLUDED.image_url;
